# generated by regen.rb from fixtures/dot.rb: the same kernel, timed
def dot(x, y, n)
  sum = 0.0
  j = 0
  while j < n
    sum = sum + x[j] * y[j]
    j = j + 1
  end
  sum
end

n = 100_000
x = Array.new(n, 0.0)
y = Array.new(n, 0.0)
i = 0
while i < n
  x[i] = 1.0 / (i + 1)
  y[i] = (i % 7 - 3) * 1.0e10 + 1.0 / (i + 3)
  i = i + 1
end
t = 0.0
r = 0
while r < 1000
  t = t + dot(x, y, n)
  r = r + 1
end
p t
